/**
 * site-links.js — the "Skill-author page:" footer shared by fetch-lesson.js and
 * state.js.
 *
 * references/site-links.json is GENERATED by site/generator/build.js from
 * references/state/author-facts.json (never hand-edit it; rebuild instead). It
 * maps lessons, state pages and facts to the ccinternals.dev/cowork/ page that
 * covers them for skill authors.
 *
 * Selection rule (pickSlugs): each key maps to [slug, citations] pairs, where
 * citations is how many facts on that page cite the key. At most MAX_LINKS
 * pages are printed, chosen by weight so the output is deterministic and the
 * model relays a URL rather than choosing one:
 *   - one or two pages: the top page alone if it holds at least twice the
 *     second's citations, else both;
 *   - three or more: the top page if it holds a strict majority AND at least
 *     twice the runner-up; else the top two if together they hold a strict
 *     majority AND the second strictly beats the third; else the section hub.
 */

'use strict';

const fs = require('fs');
const path = require('path');

const REF = 'ref=skill';
const MAX_LINKS = 2;
const LABEL = 'Skill-author page:';

/**
 * Load site-links.json from a references dir. Missing, unparseable, or without a
 * usable absolute `base` -> null (no footer), never a footer reading "undefined".
 */
function loadSiteLinks(refsDir) {
  const p = path.join(refsDir, 'site-links.json');
  if (!fs.existsSync(p)) return null;
  let links;
  try {
    links = JSON.parse(fs.readFileSync(p, 'utf8'));
  } catch (e) {
    process.stderr.write(`Warning: could not parse site-links.json: ${e.message}\n`);
    return null;
  }
  if (!validBase(links && links.base)) {
    process.stderr.write('Warning: site-links.json has no valid https base URL; no page link printed.\n');
    return null;
  }
  return links;
}

function validBase(base) {
  return typeof base === 'string' && /^https:\/\/[^\s?#]+\/$/.test(base);
}

function hubUrl(links) {
  return `${links.base}?${REF}`;
}

function pageUrl(links, slug) {
  return slug === 'index' ? hubUrl(links) : `${links.base}${slug}/?${REF}`;
}

/** Merge [slug, n] pair lists, summing weights; sorted n desc, ties by slug. */
function mergeWeights(...lists) {
  const w = new Map();
  for (const list of lists) {
    for (const item of list || []) {
      const [slug, n] = Array.isArray(item) ? item : [item, 1];
      w.set(slug, (w.get(slug) || 0) + (Number(n) || 0));
    }
  }
  return [...w].sort(([a, na], [b, nb]) => nb - na || (a < b ? -1 : a > b ? 1 : 0));
}

/**
 * Apply the selection rule to a weighted list. Returns the slugs to link, or
 * ['index'] for the hub, or [] when there is nothing to link.
 */
function pickSlugs(weighted) {
  const w = mergeWeights(weighted).filter(([, n]) => n > 0);
  if (!w.length) return [];
  const total = w.reduce((s, [, n]) => s + n, 0);
  const [[s1, n1], [s2, n2] = [null, 0], [, n3] = [null, 0]] = w;
  if (w.length <= 2) return n1 >= 2 * n2 ? [s1] : [s1, s2];
  if (2 * n1 > total && n1 >= 2 * n2) return [s1];
  if (2 * (n1 + n2) > total && n2 > n3) return [s1, s2];
  return ['index'];
}

/** Footer URLs for a weighted [slug, n] list (bare slugs count 1), after pickSlugs. */
function footerUrls(links, weighted) {
  if (!links || !validBase(links.base)) return [];
  return [...new Set(pickSlugs(weighted).map(s => pageUrl(links, s)))];
}

function footerLines(links, weighted) {
  return footerUrls(links, weighted).map(u => `${LABEL} ${u}`);
}

/** Weighted [slug, n] pairs a lesson (by topic-index `id`) maps to. */
function slugsForLesson(links, id) {
  return (links && links.by_lesson && links.by_lesson[String(id)]) || [];
}

/**
 * Footer for a topic-index lesson: { lines, error }. site-links.json is keyed by
 * the topic-index `id` fetch-lesson.js looks lessons up by; topic-index also
 * carries `lesson_number`, which differs from `id` for L1-L50. build.js refuses
 * to emit such a citation, and if one reaches the map anyway this returns no
 * lines and an error rather than attach a page to the wrong lesson.
 */
function lessonFooter(links, lesson) {
  const weighted = slugsForLesson(links, lesson.id);
  if (!weighted.length) return { lines: [], error: null };
  if (lesson.lesson_number !== undefined && String(lesson.lesson_number) !== String(lesson.id)) {
    return {
      lines: [],
      error: `site-links.json maps lesson id ${lesson.id}, whose lesson_number is "${lesson.lesson_number}" — ` +
        'numbering mismatch, no page link printed. Rebuild with site/generator/build.js.',
    };
  }
  return { lines: footerLines(links, weighted), error: null };
}

/** Weighted [slug, n] pairs a state page (by frontmatter `domain`) maps to. */
function slugsForStatePage(links, domain) {
  return (links && links.by_state_page && links.by_state_page[domain]) || [];
}

module.exports = {
  loadSiteLinks, footerUrls, footerLines, lessonFooter, pageUrl, hubUrl, pickSlugs, mergeWeights,
  slugsForLesson, slugsForStatePage, validBase, MAX_LINKS, LABEL,
};
